// Ordered turn-by-turn instructions generated by the backend from the route graph.
import type { RouteInstruction } from '../../../navigation/types'
import { useApp } from '../../PlannerContext'

interface Props {
  instructions: RouteInstruction[]
  activeStep: number | null
  emptyText: string
}

export function StepList({ instructions, activeStep, emptyText }: Props) {
  const { m } = useApp()
  const n = m.navigation
  if (instructions.length === 0) {
    return <p className="rounded-2xl bg-ink-100 p-4 text-center text-sm text-ink-500">{emptyText}</p>
  }
  return (
    <ol className="space-y-2" aria-label={n.steps}>
      {instructions.map((ins, i) => {
        const active = activeStep === i
        const done = activeStep !== null && i < activeStep
        return (
          <li key={ins.step} aria-current={active ? 'step' : undefined}
            className={`flex gap-3 rounded-xl p-3 text-sm shadow-card ring-1 ${active ? 'bg-brand-50 ring-brand-500' : 'bg-white ring-ink-100'} ${done ? 'opacity-60' : ''}`}>
            <span className={`grid h-7 w-7 shrink-0 place-items-center rounded-full text-xs font-bold ${active || done ? 'bg-brand-600 text-white' : 'bg-brand-50 text-brand-700'}`}>
              {done ? '✓' : ins.step}
            </span>
            <span className="text-ink-900">{ins.text}</span>
          </li>
        )
      })}
    </ol>
  )
}
